const foundationLessons = [
 {id:'L',name:'The letter L',sub:'Your first handshape',desc:'A simple shape. A great place to start.',steps:['Point your index finger up and extend your thumb to the side.','Curl your middle, ring, and pinky fingers into your palm.','Face your palm forward. Keep the L shape relaxed.'],tip:'Think of your thumb and index finger as the two sides of a capital L.'},
 {id:'I',name:'The letter I',sub:'One finger, clearly',desc:'A small shape with a little pinky.',steps:['Make a relaxed fist, with your palm facing forward.','Lift your pinky straight up. Keep your other fingers curled.','Rest your thumb across the curled fingers.'],tip:'Relax your wrist. Only your pinky needs to be extended.'},
 {id:'Y',name:'The letter Y',sub:'Find your stretch',desc:'Give your thumb and pinky a little space.',steps:['Extend your thumb out to the side and lift your pinky.','Curl your index, middle, and ring fingers into your palm.','Face your palm forward and hold the shape comfortably.'],tip:'You do not need to stretch hard. Keep your three middle fingers relaxed.'},
 {id:'V',name:'The letter V',sub:'Two fingers apart',desc:'Two fingers, with a little space between.',steps:['Extend your index and middle fingers upward.','Separate those fingers into a V. Curl your ring and pinky fingers.','Rest your thumb over your curled fingers, palm facing forward.'],tip:'The gap matters: keep a visible space between your two raised fingers.'},
 {id:'W',name:'The letter W',sub:'Make room for three',desc:'Add a third finger to your practice.',steps:['Raise and spread your index, middle, and ring fingers.','Curl your pinky down and hold it gently with your thumb.','Keep your palm facing forward.'],tip:'Let your three raised fingers fan out comfortably.'},
 {id:'ILY',name:'I love you',sub:'Put the shapes together',desc:'Combine the I, L, and Y handshapes.',steps:['Extend your thumb, index finger, and pinky.','Keep your middle and ring fingers curled into your palm.','Face your palm toward the person you are addressing.'],tip:'This handshape combines I, L, and Y — the initials of “I love you.”'}
];

const additions = {"A": ["Make a gentle fist with all four fingers curled.", "Keep your thumb upright beside your index finger, rather than across the front."], "B": ["Extend four fingers upward and keep them together.", "Fold your thumb across your palm."], "C": ["Curve your fingers and thumb toward each other without touching.", "Keep an open, rounded space shaped like a C."], "D": ["Point your index finger upward.", "Bring your thumb and the other fingertips together into a small circle below it."], "E": ["Bend all four fingers so their tips curl toward the palm.", "Bring your thumb across underneath the curled fingertips."], "F": ["Touch the tips of your thumb and index finger to make a small circle.", "Keep your middle, ring, and pinky fingers extended and slightly spread."], "G": ["Extend your index finger horizontally and keep your thumb beside it.", "Curl the other fingers; hold the hand sideways as shown."], "H": ["Extend your index and middle fingers together horizontally.", "Curl the ring finger and pinky, with your thumb resting against them."], "J": ["Start with your pinky extended and the other fingers curled, as for I.", "Move your hand so the pinky traces a J: down, then curve the bottom. Watch a moving demonstration as well as the diagram."], "K": ["Raise and separate your index and middle fingers.", "Place your thumb against the base of the middle finger between the two raised fingers."], "M": ["Make a fist with your thumb tucked beneath the index, middle, and ring fingers.", "Let the thumb tip sit between your ring finger and pinky."], "N": ["Tuck your thumb beneath your index and middle fingers.", "Let the thumb tip sit between your middle and ring fingers."], "O": ["Curve your fingers downward toward your thumb.", "Touch your fingertips to your thumb to close the rounded O shape."], "P": ["Make the K handshape: index and middle extended, thumb against the middle finger.", "Turn the hand downward so the middle finger points toward the floor."], "Q": ["Make the G handshape, with your index finger and thumb extended.", "Rotate the whole G shape downward: both the index and thumb point toward the floor, with a small gap between them."], "R": ["Raise your index and middle fingers and cross them.", "Curl the remaining fingers, resting your thumb against them."], "S": ["Curl all four fingers into a relaxed fist.", "Place your thumb across the front of the curled fingers."], "T": ["Curl your fingers while tucking your thumb under the index finger.", "Let the thumb tip appear between the index and middle fingers."], "U": ["Extend your index and middle fingers upward and keep them touching.", "Curl your ring finger and pinky, with your thumb resting across them."], "X": ["Curl the middle, ring, and pinky fingers into your palm.", "Raise your index finger with its joints bent into a hook; keep your thumb tucked."], "Z": ["Extend your index finger and curl the other fingers.", "Trace a Z in the air: across the top, diagonally back down, then across the bottom. Follow the diagram and a moving demonstration."]};
export const lessons = Array.from('ABCDEFGHIJKLMNOPQRSTUVWXYZ', id => {
 const existing=foundationLessons.find(l=>l.id===id);
 return {...(existing||{id,name:`The letter ${id}`,sub:'Visual handshape guide',desc:'Look closely, then shape it with your hand.',steps:additions[id],tip:'Compare the thumb, finger positions, and hand angle with the illustration.'}),image:`images/${id}.svg`,motion:id==='J'||id==='Z'};
});
lessons.push({...foundationLessons.find(l=>l.id==='ILY'),image:null,motion:false});
